// Open-Meteo's geocoder returns an empty object (no `results`) for a miss,
// which would surface downstream as a confusing expression error — fail here
// with a message that says what to fix instead.
const cfg = $('Config').first().json;
const res = $input.first().json;
const hit = res && Array.isArray(res.results) && res.results[0];
if (!hit) {
  throw new Error(`Open-Meteo could not find "${cfg.cityName}". The geocoder matches local spellings too - try "Lisboa", "Ciudad de M\u00e9xico", or add more of the name.`);
}
return [{ json: { place: {
  name: hit.name,
  admin1: hit.admin1 || '',
  country: hit.country || '',
  latitude: hit.latitude,
  longitude: hit.longitude,
  timezone: hit.timezone || 'auto',
} } }];

// Maps the raw Open-Meteo responses to everything the video needs: WMO
// weather code -> condition label + icon glyph + palette, localized strings,
// weekday names. The palette drives the whole design, so a rainy day
// genuinely looks different from a sunny one.

// One palette per sky. The whole video recolors from this: background gradient,
// glow, chips, card strokes, icons. A rainy day genuinely looks different from
// a sunny one.
const LOOKS = {
  sunny: {
    key: 'sunny',
