  61: { icon: 'rain',   look: 'rain',   label: { en: 'Light rain',           es: 'Lluvia ligera' } },
  63: { icon: 'rain',   look: 'rain',   label: { en: 'Rain',                 es: 'Lluvia' } },
  65: { icon: 'rain',   look: 'rain',   label: { en: 'Heavy rain',           es: 'Lluvia intensa' } },
  66: { icon: 'rain',   look: 'rain',   label: { en: 'Freezing rain',        es: 'Lluvia helada' } },
  67: { icon: 'rain',   look: 'rain',   label: { en: 'Freezing rain',        es: 'Lluvia helada' } },
  71: { icon: 'snow',   look: 'snow',   label: { en: 'Light snow',           es: 'Nieve ligera' } },
  73: { icon: 'snow',   look: 'snow',   label: { en: 'Snow',                 es: 'Nieve' } },
  75: { icon: 'snow',   look: 'snow',   label: { en: 'Heavy snow',           es: 'Nieve intensa' } },
  77: { icon: 'snow',   look: 'snow',   label: { en: 'Snow grains',          es: 'Granos de nieve' } },
  80: { icon: 'rain',   look: 'rain',   label: { en: 'Light showers',        es: 'Chubascos ligeros' } },
  81: { icon: 'rain',   look: 'rain',   label: { en: 'Rain showers',         es: 'Chubascos' } },
  82: { icon: 'rain',   look: 'rain',   label: { en: 'Heavy showers',        es: 'Chubascos intensos' } },
  85: { icon: 'snow',   look: 'snow',   label: { en: 'Snow showers',         es: 'Chubascos de nieve' } },
  86: { icon: 'snow',   look: 'snow',   label: { en: 'Snow showers',         es: 'Chubascos de nieve' } },
  95: { icon: 'storm',  look: 'storm',  label: { en: 'Thunderstorm',         es: 'Tormenta eléctrica' } },
  96: { icon: 'storm',  look: 'storm',  label: { en: 'Thunderstorm w/ hail', es: 'Tormenta con granizo' } },
  99: { icon: 'storm',  look: 'storm',  label: { en: 'Thunderstorm w/ hail', es: 'Tormenta con granizo' } },
};
const WMO_FALLBACK = { icon: 'cloud', look: 'cloudy', label: { en: 'Mixed skies', es: 'Cielo variable' } };

// Small UI strings, keyed by the language part of `locale`.
const UI_STRINGS = {
  en: { high: 'H', low: 'L', rain: 'RAIN', wind: 'WIND', feelsLike: 'FEELS LIKE', nextDays: 'NEXT 3 DAYS', updated: 'UPDATED', today: 'today' },
  es: { high: 'MÁX', low: 'MÍN', rain: 'LLUVIA', wind: 'VIENTO', feelsLike: 'SENSACIÓN', nextDays: 'PRÓXIMOS 3 DÍAS', updated: 'ACTUALIZADO', today: 'hoy' },
};

const r2 = (n) => Math.round(n * 100) / 100;
const r4 = (n) => Math.round(n * 10000) / 10000;
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const cap = (s, locale) => (s ? s.charAt(0).toLocaleUpperCase(locale) + s.slice(1) : s);
const deg = (n) => (Number.isFinite(n) ? `${Math.round(n)}°` : '—');
const pct = (n) => (Number.isFinite(n) ? `${Math.round(n)}%` : '—');

// Turns the two Open-Meteo responses into everything the video needs:
// labels, icon keys, palette, localized strings, rounded numbers.

function buildWeather(config, place, forecast) {
  if (!forecast || !forecast.current || !forecast.daily) {
    throw new Error('Open-Meteo returned no forecast. Response: ' + JSON.stringify(forecast || {}).slice(0, 300));
  }
  const locale = String(config.locale || 'en-US');
  const langKey = locale.split('-')[0].toLowerCase();
  const strings = UI_STRINGS[langKey] || UI_STRINGS.en;
  const lang = UI_STRINGS[langKey] ? langKey : 'en';

  const cur = forecast.current;
  const daily = forecast.daily;
  const times = daily.time || [];
  if (times.length < 4) {
    throw new Error(`Expected 4 daily entries (today + 3), got ${times.length}. Keep forecast_days=4 on the Get forecast node.`);
  }

  const wmo = (code) => WMO[code] || WMO_FALLBACK;
  const label = (code) => wmo(code).label[lang] || wmo(code).label.en;

  // Parse ISO dates as plain Y-M-D so the weekday never shifts across timezones.
  const dayName = (iso) => {
    const [y, m, d] = String(iso).split('-').map(Number);
    return cap(new Date(y, m - 1, d).toLocaleDateString(locale, { weekday: 'long' }), locale);
  };
  const dateLine = (() => {
    const [y, m, d] = String(times[0]).split('-').map(Number);
    return cap(new Date(y, m - 1, d).toLocaleDateString(locale, { weekday: 'long', month: 'long', day: 'numeric' }), locale);
  })();

  const currentMeta = wmo(cur.weather_code);
  const days = [1, 2, 3].map((i) => {
    const meta = wmo(daily.weather_code[i]);
    return {
      date: times[i],
      dayLabel: dayName(times[i]),
      hi: daily.temperature_2m_max[i],
      lo: daily.temperature_2m_min[i],
      precip: daily.precipitation_probability_max[i],
      code: daily.weather_code[i],
      label: label(daily.weather_code[i]),
      icon: meta.icon,
      accent: LOOKS[meta.look].accent,
    };
  });

  return {
    place: {
      name: place.name,
      country: place.country || '',
      label: place.country ? `${place.name} · ${place.country}` : place.name,
    },
    dateLine,
    updatedTime: String(cur.time || '').slice(11, 16),
    units: {
      temp: (forecast.current_units && forecast.current_units.temperature_2m) || '°C',
      wind: ((forecast.current_units && forecast.current_units.wind_speed_10m) || 'km/h').toUpperCase(),
    },
    current: {
      temp: cur.temperature_2m,
      feelsLike: cur.apparent_temperature,
      humidity: cur.relative_humidity_2m,
      wind: cur.wind_speed_10m,
      hi: daily.temperature_2m_max[0],
      lo: daily.temperature_2m_min[0],
      precip: daily.precipitation_probability_max[0],
      code: cur.weather_code,
      label: label(cur.weather_code),
      icon: currentMeta.icon,
    },
    days,
    look: LOOKS[currentMeta.look],
    strings,
    lang,
  };
}

const cfg = $('Config').first().json;
const place = $('Check city').first().json.place;
const forecast = $input.first().json;
return [{ json: { weather: buildWeather(cfg, place, forecast) } }];

// Assembles the Zvid project: a hero scene (city, date, big current temp,
// condition, hi/lo + rain + wind chips) and a 3-day outlook scene (cards
// with icon, weekday, precip, hi/lo). All colours come from the palette
// chosen by `Weather look`. Design language: news-local-update /
// dataviz-project-status from the Zvid template library.

const r2 = (n) => Math.round(n * 100) / 100;
const r4 = (n) => Math.round(n * 10000) / 10000;
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const cap = (s, locale) => (s ? s.charAt(0).toLocaleUpperCase(locale) + s.slice(1) : s);
const deg = (n) => (Number.isFinite(n) ? `${Math.round(n)}°` : '—');
const pct = (n) => (Number.isFinite(n) ? `${Math.round(n)}%` : '—');

// Line-style weather icons drawn in a 24-unit box, scaled into place.
// Stroke-only (no <text> — SVG text gets no fonts in the renderer).
const ICONS = {
  sun: [
    "<circle cx='12' cy='12' r='4.6'/>",
    "<path d='M12 1.6v2.6'/>", "<path d='M12 19.8v2.6'/>",
    "<path d='M4.65 4.65l1.85 1.85'/>", "<path d='M17.5 17.5l1.85 1.85'/>",
    "<path d='M1.6 12h2.6'/>", "<path d='M19.8 12h2.6'/>",
    "<path d='M4.65 19.35l1.85-1.85'/>", "<path d='M17.5 6.5l1.85-1.85'/>",
  ],
  cloud: [
    "<path d='M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z'/>",
  ],
  partly: [
    "<circle cx='7.4' cy='7.2' r='2.7'/>",
    "<path d='M7.4 2.2v1.6'/>", "<path d='M2.4 7.2h1.6'/>",
    "<path d='M3.9 3.7l1.15 1.15'/>", "<path d='M10.9 3.7l-1.15 1.15'/>",
    "<path d='M2.9 10.7l1.15-1.15'/>",
    "<g transform='translate(4.9 5.9) scale(0.76)'><path d='M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z' fill='OCCLUDE'/></g>",
  ],
  fog: [
    "<g transform='translate(0 -2.6)'><path d='M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z'/></g>",
    "<path d='M5.5 19.6h13'/>", "<path d='M8 22.6h8'/>",
  ],
  rain: [
    "<path d='M20 16.58A5 5 0 0 0 18 7h-1.26A8 8 0 1 0 4 15.25'/>",
    "<path d='M8 14.8v4.4'/>", "<path d='M12 16.8v4.4'/>", "<path d='M16 14.8v4.4'/>",
  ],
  snow: [
    "<path d='M20 16.58A5 5 0 0 0 18 7h-1.26A8 8 0 1 0 4 15.25'/>",
    "<circle cx='8' cy='16' r='1.15' fill='DOT' stroke='none'/>",
    "<circle cx='8' cy='20' r='1.15' fill='DOT' stroke='none'/>",
    "<circle cx='12' cy='18' r='1.15' fill='DOT' stroke='none'/>",
    "<circle cx='12' cy='22' r='1.15' fill='DOT' stroke='none'/>",
    "<circle cx='16' cy='16' r='1.15' fill='DOT' stroke='none'/>",
    "<circle cx='16' cy='20' r='1.15' fill='DOT' stroke='none'/>",
  ],
  storm: [
    "<path d='M19 16.9A5 5 0 0 0 18 7h-1.26a8 8 0 1 0-11.62 9'/>",
    "<polyline points='13 11 9 17 15 17 11 23'/>",
  ],
};

function iconSvg(kind, cx, cy, size, color, opts) {
  const o = opts || {};
  const scale = r4(size / 24);
  const tx = r2(cx - size / 2);
  const ty = r2(cy - size / 2);
  const inner = (ICONS[kind] || ICONS.cloud)
    .join('')
    .replace(/OCCLUDE/g, o.occlude || 'none')
    .replace(/DOT/g, color);
  return `<g transform='translate(${tx} ${ty}) scale(${scale})' opacity='${o.opacity != null ? o.opacity : 1}' fill='none' stroke='${color}' stroke-width='1.7' stroke-linecap='round' stroke-linejoin='round'>${inner}</g>`;
}

// Per-look ambient decoration for the hero, kept in the side bands so it never
// sits under text.
function heroDecor(look) {
  const a = look.accent;
  if (look.key === 'sunny' || look.key === 'storm') {
    return `<circle cx='540' cy='800' r='310' fill='none' stroke='${a}' stroke-opacity='0.10' stroke-width='1.5'/>` +
      `<circle cx='540' cy='800' r='400' fill='none' stroke='${a}' stroke-opacity='0.06' stroke-width='1.5'/>` +
      `<circle cx='540' cy='800' r='490' fill='none' stroke='${a}' stroke-opacity='0.035' stroke-width='1.5'/>`;
  }
  if (look.key === 'rain') {
    const drop = (x, y) => `<path d='M${x} ${y}l-14 42' stroke='${a}' stroke-opacity='0.16' stroke-width='3' stroke-linecap='round'/>`;
    return drop(140, 560) + drop(215, 750) + drop(120, 980) + drop(195, 1210) +
      drop(905, 520) + drop(960, 730) + drop(880, 950) + drop(945, 1180);
  }
  if (look.key === 'snow') {
    const dot = (x, y, r) => `<circle cx='${x}' cy='${y}' r='${r}' fill='${a}' fill-opacity='0.18'/>`;
    return dot(150, 560, 6) + dot(220, 780, 4) + dot(130, 1010, 5) + dot(205, 1230, 4) +
      dot(910, 540, 5) + dot(950, 760, 6) + dot(880, 990, 4) + dot(935, 1200, 5);
  }
  // cloudy / fog: ghost cloud bands
  return `<rect x='640' y='420' width='330' height='34' rx='17' fill='rgba(255,255,255,0.035)'/>` +
    `<rect x='110' y='500' width='240' height='30' rx='15' fill='rgba(255,255,255,0.03)'/>` +
    `<rect x='700' y='1180' width='260' height='30' rx='15' fill='rgba(255,255,255,0.03)'/>`;
}

function buildProject(config, weather) {
  const W = weather;
  const look = W.look;
  const S = W.strings;
  const heroSec = r2(Number(config.heroSeconds ?? 6.4));
  const outSec = r2(Number(config.outlookSeconds ?? 5.8));
  const tSec = r2(Number(config.transitionSeconds ?? 0.5));
  const font = 'Sora';
  const subFont = 'Outfit';

  // ---- hero scene backdrop ----
  const heroSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs>` +
    `<linearGradient id='wxBg' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='${look.bg1}'/><stop offset='1' stop-color='${look.bg2}'/></linearGradient>` +
    `<radialGradient id='wxGlow' cx='0.5' cy='0.5' r='0.5'><stop offset='0' stop-color='${look.glow}' stop-opacity='0.30'/><stop offset='0.55' stop-color='${look.glow}' stop-opacity='0.12'/><stop offset='1' stop-color='${look.glow}' stop-opacity='0'/></radialGradient>` +
    `</defs>` +
    `<rect width='1080' height='1920' fill='url(#wxBg)'/>` +
    `<circle cx='540' cy='800' r='460' fill='url(#wxGlow)'/>` +
    heroDecor(look) +
    iconSvg(W.current.icon, 540, 780, 270, look.accent, { occlude: look.bg1 }) +
    `</svg>`;

  // ---- outlook scene backdrop (cards + per-day icons) ----
  const cardY = [560, 920, 1280];
  const cardH = 320;
  let outlookSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs>` +
    `<linearGradient id='wxBg2' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='${look.bg1}'/><stop offset='1' stop-color='${look.bg2}'/></linearGradient>` +
    `<radialGradient id='wxGlow2' cx='0.5' cy='0.5' r='0.5'><stop offset='0' stop-color='${look.glow}' stop-opacity='0.22'/><stop offset='1' stop-color='${look.glow}' stop-opacity='0'/></radialGradient>` +
    `</defs>` +
    `<rect width='1080' height='1920' fill='url(#wxBg2)'/>` +
    `<circle cx='540' cy='230' r='420' fill='url(#wxGlow2)'/>`;
  W.days.forEach((d, i) => {
    const y = cardY[i];
    const cy = y + cardH / 2;
    outlookSvg +=
      `<rect x='90' y='${y}' width='900' height='${cardH}' rx='40' fill='rgba(255,255,255,0.035)' stroke='${look.panelStroke}' stroke-width='1.5'/>` +
      `<circle cx='225' cy='${cy}' r='92' fill='rgba(255,255,255,0.045)'/>` +
      iconSvg(d.icon, 225, cy, 148, d.accent, { occlude: look.bg1 });
  });
  outlookSvg += `</svg>`;

  // ---- hero text stack ----
  const chip = (content) =>
    `<span style='display:inline-block; background:${look.panel}; border:1.5px solid ${look.panelStroke}; border-radius:999px; padding:16px 28px; margin:0 9px 14px; font-size:28px; font-weight:700; letter-spacing:2px; color:${look.soft}; white-space:nowrap;'>${content}</span>`;

  const heroVisuals = [
    { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: heroSec, svg: heroSvg },
    {
      type: 'TEXT', x: 540, y: 150, anchor: 'top-center', track: 1,
      enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: heroSec,
      style: { fontFamily: subFont, color: look.accent },
      html: `<div style='text-align:center; color:${look.accent}; font-size:30px; font-weight:800; letter-spacing:8px;'>${esc(config.brandName || 'DAILY WEATHER')}</div>`,
    },
    {
      type: 'TEXT', x: 540, y: 268, width: 980, anchor: 'top-center', track: 2,
      enterBegin: 0.2, enterEnd: 0.7, enterAnimation: 'smoothup', exitEnd: heroSec,
      style: { fontFamily: font, color: '#FFFFFF' },
      html: `<div style='text-align:center; color:#FFFFFF; font-size:96px; line-height:1.04; font-weight:800; letter-spacing:-2px;'>${esc(W.place.name)}</div>` +
        `<div style='margin-top:18px; text-align:center; color:${look.muted}; font-size:30px; font-weight:600; letter-spacing:5px;'>${esc(W.dateLine.toUpperCase())}</div>`,
    },
    {
      type: 'TEXT', x: 540, y: 940, width: 1000, anchor: 'top-center', track: 3,
      enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'smoothup', exitEnd: heroSec,
      style: { fontFamily: font, color: '#FFFFFF' },
      html: `<div style='text-align:center; color:#FFFFFF; font-size:290px; line-height:1; font-weight:800; letter-spacing:-8px;'>${deg(W.current.temp)}</div>` +
        `<div style='margin-top:20px; text-align:center; color:${look.accent}; font-size:46px; font-weight:700; letter-spacing:1px;'>${esc(W.current.label)}</div>` +
        `<div style='margin-top:18px; text-align:center; color:${look.muted}; font-size:27px; font-weight:600; letter-spacing:3px;'>${esc(S.feelsLike)} ${deg(W.current.feelsLike)}</div>`,
    },
    {
      type: 'TEXT', x: 540, y: 1490, width: 1020, anchor: 'top-center', track: 4,
      enterBegin: 0.75, enterEnd: 1.2, enterAnimation: 'fade', exitEnd: heroSec,
      style: { fontFamily: subFont, color: look.soft },
      html: `<div style='text-align:center;'>` +
        chip(`${esc(S.high)} ${deg(W.current.hi)} / ${esc(S.low)} ${deg(W.current.lo)}`) +
        chip(`${esc(S.rain)} ${pct(W.current.precip)}`) +
        chip(`${esc(S.wind)} ${Math.round(W.current.wind)} ${esc(W.units.wind)}`) +
        `</div>`,
    },
    {
      type: 'TEXT', x: 540, y: 1795, anchor: 'center-center', track: 5,
      enterBegin: 1.0, enterEnd: 1.4, enterAnimation: 'fade', exitEnd: heroSec,
      style: { fontFamily: subFont, color: look.muted },
      html: `<div style='color:${look.muted}; font-size:24px; font-weight:700; letter-spacing:4px;'>${esc(config.handle || config.brandName || '')} · ${esc(S.updated)} ${esc(W.updatedTime)}</div>`,
    },
  ];

  // ---- outlook text stack ----
  const outlookVisuals = [
    { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: outSec, svg: outlookSvg },
    {
      type: 'TEXT', x: 100, y: 290, width: 880, anchor: 'top-left', track: 1,
      enterBegin: 0.12, enterEnd: 0.55, enterAnimation: 'smoothright', exitEnd: outSec,
      style: { fontFamily: font, color: look.accent },
      html: `<div style='color:${look.accent}; font-size:32px; font-weight:800; letter-spacing:7px;'>${esc(S.nextDays)}</div>` +
        `<div style='margin-top:14px; color:${look.muted}; font-size:27px; font-weight:600; letter-spacing:2px;'>${esc(W.place.label)}</div>`,
    },
  ];
  W.days.forEach((d, i) => {
    outlookVisuals.push({
      type: 'TEXT', x: 360, y: cardY[i] + cardH / 2, width: 550, anchor: 'center-left', track: 2 + i,
      enterBegin: r2(0.3 + i * 0.2), enterEnd: r2(0.75 + i * 0.2), enterAnimation: 'smoothleft', exitEnd: outSec,
      style: { fontFamily: font, color: '#FFFFFF' },
      html: `<div style='display:flex; align-items:center; justify-content:space-between; width:550px;'>` +
        `<div>` +
        `<div style='color:#FFFFFF; font-size:52px; font-weight:700; line-height:1.05;'>${esc(d.dayLabel)}</div>` +
        `<div style='margin-top:12px; color:${d.accent}; font-size:26px; font-weight:700; letter-spacing:3px;'>${esc(S.rain)} ${pct(d.precip)}</div>` +
        `</div>` +
        `<div style='color:#FFFFFF; font-size:60px; font-weight:800; white-space:nowrap;'>${deg(d.hi)}<span style='color:${look.muted}; font-size:42px; font-weight:600;'> / ${deg(d.lo)}</span></div>` +
        `</div>`,
    });
  });
  outlookVisuals.push({
    type: 'TEXT', x: 540, y: 1780, anchor: 'center-center', track: 5,
    enterBegin: 1.0, enterEnd: 1.4, enterAnimation: 'fade', exitEnd: outSec,
    style: { fontFamily: subFont, color: look.muted },
    html: `<div style='color:${look.muted}; font-size:24px; font-weight:700; letter-spacing:4px;'>${esc(config.brandName || '')} · ${esc(W.dateLine.toUpperCase())}</div>`,
  });

  const safeName = `daily-weather-${W.place.name}`.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'daily-weather';

  const payload = {
    name: safeName,
    resolution: config.resolution || 'instagram-reel',
    frameRate: Number(config.frameRate ?? 30),
    backgroundColor: look.bg2,
    outputFormat: 'mp4',
    scenes: [
      {
        id: 'hero',
        duration: heroSec,
        backgroundColor: look.bg2,
        transition: 'smoothup',
        transitionId: 'outlook',
        transitionDuration: tSec,
        visuals: heroVisuals,
      },
      {
        id: 'outlook',
        duration: outSec,
        backgroundColor: look.bg2,
        visuals: outlookVisuals,
      },
    ],
  };

  if (config.musicUrl) {
    // NOTE: no track field on audios — the production API rejects audios[].track.
    payload.audios = [{ src: config.musicUrl, volume: Number(config.musicVolume ?? 0.14) }];
  }

  const caption =
    `${W.place.name} ${S.today}: ${W.current.label} · ${deg(W.current.temp)}${W.units.temp.replace('°', '')} · ` +
    `${S.high} ${deg(W.current.hi)} / ${S.low} ${deg(W.current.lo)} · ${S.rain} ${pct(W.current.precip)}` +
    ` #${W.place.name.replace(/\s+/g, '')} #weather`;

  return {
    payload,
    meta: {
      city: W.place.name,
      country: W.place.country,
      dateLine: W.dateLine,
      condition: W.current.label,
      lookKey: look.key,
      tempNow: deg(W.current.temp),
      hiLo: `${deg(W.current.hi)} / ${deg(W.current.lo)}`,
      precip: pct(W.current.precip),
      totalSeconds: r2(heroSec + outSec - tSec),
      sceneCount: payload.scenes.length,
      caption,
    },
  };
}

const cfg = $('Config').first().json;
const weather = $('Weather look').first().json.weather;
const { payload, meta } = buildProject(cfg, weather);
return [{ json: { payload, meta } }];

// The free validate endpoint runs the exact pipeline a render submission
// runs, so a failure here is a payload bug - surface the field list instead
// of a generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => `  - ${d.field}: ${d.message}`).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error(`Zvid rejected the project (HTTP ${status}): ${body.message || body.error}\n${details}`);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open the editorLink to watch
// the draft, then set dryRun to false in Config to go live.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = `${String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '')}/?project=${project.id}`;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    city: d.meta.city,
    condition: d.meta.condition,
    look: d.meta.lookKey,
    dateLine: d.meta.dateLine,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalSeconds,
    caption: d.meta.caption,
    warnings: d.warnings,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(`Render did not finish within ${cfg.timeoutMinutes} minutes (job ${job.id}, state ${job.state}).`);
}

return $input.all();

// Final report. `videoUrl` + `caption` are everything a publishing tail
// needs - see the sticky note on the right.
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result && job.result.url);

return [{
  json: {
    videoUrl: url,
    jobId: job.id,
    creditsCharged: build.creditsRequired,
    city: build.meta.city,
    country: build.meta.country,
    condition: build.meta.condition,
    look: build.meta.lookKey,
    dateLine: build.meta.dateLine,
    videoSeconds: build.meta.totalSeconds,
    caption: build.meta.caption,
  },
}];
